const PHOTOS={
  "photo1":"data:image/jpeg;base64,",
  "photo1_sq":"data:image/jpeg;base64,",
  "photo2":"data:image/jpeg;base64,",
  "photo2_sq":"data:image/jpeg;base64,",
  "photo3":"data:image/jpeg;base64,",
  "photo3_sq":"data:image/jpeg;base64,",
  "photo4":"data:image/jpeg;base64,",
  "photo4_sq":"data:image/jpeg;base64,",
  "photo5":"data:image/jpeg;base64,",
  "photo5_sq":"data:image/jpeg;base64,",
  "photo5_v":"data:image/jpeg;base64,",
  "photo6":"data:image/jpeg;base64,",
  "photo6_sq":"data:image/jpeg;base64,",
  "photo7":"data:image/jpeg;base64,",
  "photo7_sq":"data:image/jpeg;base64,",
  "photo7_v":"data:image/jpeg;base64,",
  "photo8":"data:image/jpeg;base64,",
  "photo8_sq":"data:image/jpeg;base64,",
};

document.addEventListener("DOMContentLoaded",()=>{
  document.querySelectorAll("img[data-photo]").forEach(img=>{
    const k=img.getAttribute("data-photo");
    if(PHOTOS[k]) img.src=PHOTOS[k];
  });
  const heroPhotos=["photo1","photo3","photo5","photo7"];
  heroPhotos.forEach((k,i)=>{
    const el=document.getElementById("hs"+i);
    if(el && PHOTOS[k]) el.style.backgroundImage=`url(${PHOTOS[k]})`;
  });
});
